        if($action==='favorable'){
            [$tlat,$tlon]=parsePoint($p['target']??[],'цели');[$clat,$clon]=parsePoint($p['launch_center']??[],'центра запуска');$ss=utc((string)$p['search_start']);$se=utc((string)$p['search_end']);if($se<=$ss)throw new RuntimeException('Конец периода должен быть позже начала.');$hours=(float)($p['duration_hours']??5);$step=(float)($p['step_minutes']??2);$rad=(float)($p['launch_radius_m']??1000);$targetRad=(float)($p['target_radius_m']??5000);$timeStep=(float)($p['time_step_hours']??1);$surfaceLimit=(float)($p['surface_wind_limit_mps']??10);$shearLimit=(float)($p['shear_limit_s_inv']??0.002);$rainLimit=(float)($p['precipitation_limit_mm']??5);$ensembleMembers=max(1,min(200,(int)($p['ensemble_members']??30)));$ensembleSigma=(float)($p['ensemble_wind_sigma_mps']??1.5);$points=ringPoints($clat,$clon,$rad,2,12);$found=[];$times=[];$t=$ss;while($t<=$se){$times[]=$t;$t=$t->modify('+'.(int)round($timeStep*3600).' seconds');}
            foreach($times as $launchTime){$forecastEnd=$launchTime->modify('+'.(int)ceil($hours*3600).' seconds');[$ls,$os]=grid(($clat+$tlat)/2,($clon+$tlon)/2,forecastRadius($hours)+$rad/1000);$fc=meteo($ls,$os,$launchTime,$forecastEnd);foreach($points as $lp){$params=['lat'=>$lp[0],'lon'=>$lp[1],'start_time'=>iso($launchTime),'start_altitude'=>(float)($p['start_altitude']??0),'ascent_rate'=>(float)($p['ascent_rate']??5),'max_altitude'=>(float)($p['max_altitude']??9000),'duration_hours'=>$hours,'step_minutes'=>$step];$tr=traj($params,$fc);$min=INF;$idx=null;foreach($tr as $j=>$pt){$d=hav($pt['lat'],$pt['lon'],$tlat,$tlon);if($d<$min){$min=$d;$idx=$j;}}$hit=false;for($j=1;$j<count($tr);$j++){if(targetHit($tr[$j-1],$tr[$j],[$tlat,$tlon],$targetRad)[0]){$hit=true;$idx=$j;break;}}if(!$hit||$idx===null)continue;[$surface,$shear]=surfaceShear($fc,$lp[0],$lp[1],$launchTime,(float)($params['max_altitude']));$hazard=weatherHazard($fc,$tr,$rainLimit);if($surface>$surfaceLimit||$shear>$shearLimit||$hazard)continue;$cut=truncateTarget($tr,$tlat,$tlon,$targetRad);$found[]=['launch_time'=>iso($launchTime),'launch_point'=>point($lp[0],$lp[1]),'min_distance_to_target_m'=>round($min,1),'recommended_time'=>iso($launchTime),'score'=>round($min/max(100,$targetRad)+$surface/max(.1,$surfaceLimit)*.05+$shear/max(1e-9,$shearLimit)*.05,4),'surface_wind_mps'=>round($surface,2),'shear_s_inv'=>$shear,'hazard_hit'=>false,'restricted_hit'=>false,'ensemble_success_rate'=>0,'ensemble_median_distance_m'=>0,'ensemble_p90_distance_m'=>0,'trajectory'=>$cut,'closest_point'=>$tr[$idx]];}}
            usort($found,fn($a,$b)=>$a['score']<=>$b['score']);$targetCount=min(count($found),max(24,(int)ceil(count($found)*.2)));$selected=array_slice($found,0,$targetCount);$seen=[];foreach($selected as $c)$seen[$c['launch_time']]=true;foreach($found as $c){if(count($selected)>=min(count($found),$targetCount+count($times)))break;if(!isset($seen[$c['launch_time']])){$selected[]=$c;$seen[$c['launch_time']]=true;}}
            foreach($selected as &$c){$dists=[];$success=0;$launchDt=utc($c['launch_time']);$efEnd=$launchDt->modify('+'.(int)ceil($hours*3600).' seconds');[$els,$eos]=grid(($clat+$tlat)/2,($clon+$tlon)/2,forecastRadius($hours)+$rad/1000);$candidateFc=meteo($els,$eos,$launchDt,$efEnd);$baseParams=['lat'=>$c['launch_point']['lat'],'lon'=>$c['launch_point']['lon'],'start_time'=>$c['launch_time'],'start_altitude'=>(float)($p['start_altitude']??0),'ascent_rate'=>(float)($p['ascent_rate']??5),'max_altitude'=>(float)($p['max_altitude']??9000),'duration_hours'=>$hours,'step_minutes'=>$step];for($m=0;$m<$ensembleMembers;$m++){try{$efc=$m===0?$candidateFc:perturbForecast($candidateFc,1009*$m+17,$ensembleSigma);$et=traj($baseParams,$efc);$ed=INF;$ehit=false;for($j=0;$j<count($et);$j++){$ed=min($ed,hav($et[$j]['lat'],$et[$j]['lon'],$tlat,$tlon));if($j>0&&targetHit($et[$j-1],$et[$j],[$tlat,$tlon],$targetRad)[0])$ehit=true;}if(is_finite($ed)){$dists[]=$ed;if($ehit)$success++;}}catch(Throwable $e){}}if($dists){sort($dists);$n=count($dists);$c['ensemble_success_rate']=$success/$n;$c['ensemble_median_distance_m']=$dists[intdiv($n,2)];$c['ensemble_p90_distance_m']=$dists[min($n-1,(int)floor(.9*($n-1)))];$c['score']=$c['ensemble_p90_distance_m']/max(100,$targetRad)-$c['ensemble_success_rate']*2+$c['min_distance_to_target_m']/max(100,$targetRad);}}
            unset($c);usort($selected,fn($a,$b)=>$a['score']<=>$b['score']);$found=$selected;json_out(['status'=>'ok','count'=>count($found),'windows'=>$found,'processed'=>count($times),'total'=>count($times)]);
        }
        fail('Неизвестный API endpoint',404);
    }catch(Throwable $e){json_out(['status'=>'error','detail'=>$e->getMessage()],502);}
}
if(isset($_GET['api']))api();
